/** Checks whether the passed props have an uncontrolled prop */
export function hasUncontrolledProp<
  T extends Record<string, unknown>,
  PropName extends string,
>(
  props: T,
  propName: string,
): props is T & { [P in keyof T as `${PropName}`]: string } {
  const prop = props[`${propName}`];

  return prop !== undefined && prop !== null;
}
